in vec2 uv0;
in vec4 color;
in float v_tintEffect;
uniform sampler2D cc_spriteTexture;
vec4 frag() {
  vec4 texture1 = texture(cc_spriteTexture, uv0);
  vec4 preMultipliedColor = vec4(texture1.rgb * texture1.a, texture1.a);
  vec4 texel = vec4(color.bgr * color.a, color.a);
  vec4 colorA = preMultipliedColor * texel;
  vec4 tempColor = color;
  if (colorA.a <= 0.3) {
    vec4 topColor = texture(cc_spriteTexture, uv0 + vec2(0.0, 1.0));
    vec4 bottomColor = texture(cc_spriteTexture, uv0 + vec2(0.0, -1.0));
    vec4 leftColor = texture(cc_spriteTexture, uv0 + vec2(-1.0, 0.0));
    vec4 rightColor = texture(cc_spriteTexture, uv0 + vec2(1.0, 0.0));
    float avgAlpha = (topColor.a + bottomColor.a + leftColor.a + rightColor.a) / 4.0;
    if (avgAlpha <= 0.3) {
      tempColor.a = 0.0;
    }
  }
  colorA = tempColor;
  return colorA;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

